/**
 * @summary Get food suggestions based on cart
 */
export const getGetSuggestionsUrl = (params?: GetSuggestionsParams) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : value.toString());
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/api/suggestions?${stringifiedParams}`
    : `/api/suggestions`;
};

export const getSuggestions = async (
  params?: GetSuggestionsParams,
  options?: RequestInit,
): Promise<MenuItem[]> => {
  return customFetch<MenuItem[]>(getGetSuggestionsUrl(params), {
    ...options,
    method: "GET",
  });
};

export const getGetSuggestionsQueryKey = (params?: GetSuggestionsParams) => {
  return [`/api/suggestions`, ...(params ? [params] : [])] as const;
};

